components.css:
.ds-preview { background: var(--color-background, #1A1917); color: var(--color-text, #F4F0E8); }
.ds-button { font-family: var(--font-body, "Funnel Sans"), "Funnel Sans", sans-serif; font-size: var(--text-body, 1rem); line-height: var(--leading-body, 1.5); display: inline-flex; align-items: center; justify-content: center; gap: var(--space-sm, 0.5rem); min-height: var(--control-height, 3rem); padding: var(--space-sm, 0.5rem) var(--space-lg, 1.5rem); border: 1px solid transparent; border-radius: var(--radius-control, 0); font-weight: 600; text-decoration: none; transition: background-color var(--duration-feedback, 120ms), color var(--duration-feedback, 120ms), border-color var(--duration-feedback, 120ms); }
.ds-primary { background: var(--color-accent, #FF5538); color: var(--color-on-accent, #1A1917); }
.ds-primary:hover:not(:disabled) { background: var(--color-text, #F4F0E8); color: var(--color-background, #1A1917); }
.ds-secondary { border-color: var(--color-border, color-mix(in srgb, #F4F0E8 50%, #1A1917)); color: var(--color-text, #F4F0E8); background: transparent; }
.ds-secondary:hover:not(:disabled) { border-color: var(--color-text, #F4F0E8); }
.ds-button:active:not(:disabled) { border-color: currentColor; }
.ds-button:disabled { opacity: 0.45; cursor: not-allowed; }
.ds-button:focus-visible, .ds-switch:focus-visible { outline: 2px solid var(--color-focus, #F4F0E8); outline-offset: var(--space-xs, 0.25rem); }@media (prefers-reduced-motion: reduce) { .ds-button, .ds-switch::before, .ds-thumb { transition-duration: 0ms; } }
.ds-button:not(:disabled), .ds-switch:not(:disabled) { cursor: pointer; }

